import{_ as t,c as a,o,ag as i}from"./chunks/framework.CQuhCYrb.js";const p=JSON.parse('{"title":"Citating a TAAW","description":"","frontmatter":{"title":"Citating a TAAW"},"headers":[],"relativePath":"general/citating-a-taaw.md","filePath":"general/citating-a-taaw.md","lastUpdated":null}'),r={name:"general/citating-a-taaw.md"};function n(s,e,l,h,c,d){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="citating-a-taaw" tabindex="-1">Citating a TAAW <a class="header-anchor" href="#citating-a-taaw" aria-label="Permalink to &quot;Citating a TAAW&quot;">​</a></h1><h2 id="taaw-citation-workflow" tabindex="-1">TAAW Citation Workflow <a class="header-anchor" href="#taaw-citation-workflow" aria-label="Permalink to &quot;TAAW Citation Workflow&quot;">​</a></h2><p>Citations are vital for showing the credibility of your work, for future research on your TA or environment, and for ensuring that future teams don&#39;t come in and change everything because they only see assumptions or surface-level research. <a href="https://socom.sharepoint-mil.us/sites/usasoc-1sfc-4pog-1bn-c/SiteAssets/Team%20Site%20Notebook/Knowledge%20Library/MISO%20Doctrine%20and%20Policy.one&amp;section-id=%7B5B68FB96-2EA8-4C6C-A43E-4D7D8F8F0A40%7D&amp;page-id=%7B35A3E9A5-A18C-4785-B4C0-1421230FCF46%7D&amp;end%7CTM" target="_blank" rel="noreferrer">3-53.11 Influence Process Activity: Target Audience Analysis (TAA)</a> details some of the common sources to cite. Starting with classified research is vital to prevent going down rabbit holes that are not supported by INTEL or, worse, which may be disputed by INTEL but actively pushed on open source by adversaries.</p><p>Citations should be included after the sentence or content using information from a different source. Cited work should include the page number if it is a report or other work with pages.</p><p>See the following resource for the NPS Guide to citing military reports, orders, and even meetings: <a href="https://libguides.nps.edu/citation" target="_blank" rel="noreferrer">NPS Citation Guide</a>.</p><h3 id="how-to-cite-with-footnotes-on-word" tabindex="-1">HOW TO CITE with FOOTNOTES on WORD <a class="header-anchor" href="#how-to-cite-with-footnotes-on-word" aria-label="Permalink to &quot;HOW TO CITE with FOOTNOTES on WORD&quot;">​</a></h3><h2 id="open-word-desktop-app-works-best-web-has-limitations" tabindex="-1">Open Word (Desktop App works best; Web has limitations). <a class="header-anchor" href="#open-word-desktop-app-works-best-web-has-limitations" aria-label="Permalink to &quot;Open Word (Desktop App works best; Web has limitations).&quot;">​</a></h2><h2 id="after-writing-sourced-information-highlight-all-related-text" tabindex="-1">After writing sourced information, highlight all related text. <a class="header-anchor" href="#after-writing-sourced-information-highlight-all-related-text" aria-label="Permalink to &quot;After writing sourced information, highlight all related text.&quot;">​</a></h2><h2 id="click-the-references-tab-at-the-top-of-the-page" tabindex="-1">Click the REFERENCES tab at the top of the page. <a class="header-anchor" href="#click-the-references-tab-at-the-top-of-the-page" aria-label="Permalink to &quot;Click the REFERENCES tab at the top of the page.&quot;">​</a></h2><h2 id="click-the-large-button-in-the-second-section-from-the-left-titled-insert-footnote" tabindex="-1">Click the large button in the second section from the left titled &quot;Insert Footnote.&quot; <a class="header-anchor" href="#click-the-large-button-in-the-second-section-from-the-left-titled-insert-footnote" aria-label="Permalink to &quot;Click the large button in the second section from the left titled &quot;Insert Footnote.&quot;&quot;">​</a></h2><ol><li>[# A corresponding numbered footnote will automatically appear at the bottom of the page.</li></ol><h2 id="insert-an-abbreviated-title-for-the-source-that-can-be-easily-distinguished-from-other-sources" tabindex="-1">Insert an abbreviated title for the source that can be easily distinguished from other sources. <a class="header-anchor" href="#insert-an-abbreviated-title-for-the-source-that-can-be-easily-distinguished-from-other-sources" aria-label="Permalink to &quot;Insert an abbreviated title for the source that can be easily distinguished from other sources.&quot;">​</a></h2><h3 id="context-of-citing-taaw" tabindex="-1">Context of CITING TAAW <a class="header-anchor" href="#context-of-citing-taaw" aria-label="Permalink to &quot;Context of CITING TAAW&quot;">​</a></h3><ul><li><p>Identify data to support claims in TAAW. See <a href="#">https://socom.sharepoint-mil.us/sites/socsouth-j3-jedpsyop/SiteAssets/SOCSOUTH%20J39%20PSYOP%20(CUI)/MISO/SOPs%20and%20Guides.one|TAAW Research</a>.</p></li><li><p>Include either a direct quote or paraphrase the information with a page number or chapter when possible. This will help teams in the future who are looking for more context on a claim.</p></li><li><p>Ensure the portion marking for that paragraph of the TAAW matches the classification of the sourced information.</p></li><li><p>At the end of the quoted information, provide a footnote reference number.</p><ul><li>I.E: The indigenous population fears the jaguar symbol 1.</li></ul></li><li><p>At the bottom of the page, include a footnote that provides an abbreviated source for all instances of quoted information on that page.</p><ul><li>I.E: 1 National Geographic.</li></ul></li><li><p>Create a bibliography page at the end of the TAAW.</p><ul><li>All sourced information should be included here with full sourcing. <ul><li>I.E. National Geographic, Indigenous beliefs, 5/6/2024, <a href="http://www.natgeo.com" target="_blank" rel="noreferrer">www.natgeo.com</a>.</li><li>I.E. (U/UU) DIA; IIR ###########, Date, report name.</li></ul></li><li>A third party with adequate clearance must be able to locate all of the listed sources.</li></ul></li><li><p>For information gathered via ground assessments, have the team write a situation/findings report to include with the bibliography. Number reports and references as such.</p></li><li><p>Use this resource to help with citations: <a href="https://libguides.nps.edu/citation" target="_blank" rel="noreferrer">Home - Citation Guide - Research Guides at Naval Postgraduate School (NPS), Dudley Knox Library (DKL)</a>.</p></li></ul><p>[Up] [Required] [<a href="Category:Guides%5D" target="_blank" rel="noreferrer">MISO</a>(/miso)</p>',15)])])}const f=t(r,[["render",n]]);export{p as __pageData,f as default};
